/**
 * adx-workflow: spec document helpers (spec mode + "Spec only — stop" picker).
 *
 * A spec is a markdown document (context & goal, research notes, decisions &
 * assumptions, acceptance-criteria checklist) written to a .md file while the
 * workspace itself stays read-only. Default location: .pi/specs/<slug>.md.
 */

import { mkdir, writeFile } from 'node:fs/promises'
import { dirname, isAbsolute, join, resolve, sep } from 'node:path'

import type { MetaEntry } from './store.js'

/** Auto-generated slug: `spec-YYYYMMDD-HHMMSS` (deterministic for tests). */
export function makeSpecSlug(date: Date = new Date()): string {
  const p = (n: number): string => String(n).padStart(2, '0')
  return `spec-${date.getFullYear()}${p(date.getMonth() + 1)}${p(date.getDate())}-${p(date.getHours())}${p(date.getMinutes())}${p(date.getSeconds())}`
}

/** Default spec path (relative to cwd): `.pi/specs/<slug>.md`. */
export function defaultSpecPath(cwd: string, date: Date = new Date()): string {
  return join('.pi', 'specs', `${makeSpecSlug(date)}.md`)
}

/**
 * Validate + resolve a spec path: must be a .md file inside the project.
 * Returns the absolute path, or undefined when invalid/absent.
 */
export function resolveSpecPath(cwd: string, rawPath?: string): string | undefined {
  if (!rawPath) return undefined
  if (specPathError(cwd, rawPath) !== undefined) return undefined
  const name = rawPath.trim()
  const abs = isAbsolute(name) ? resolve(name) : resolve(cwd, name)
  return abs
}

/** Human-readable reason a spec path is invalid (undefined when valid). */
export function specPathError(cwd: string, rawPath: string): string | undefined {
  const name = rawPath.trim()
  if (!name.toLowerCase().endsWith('.md')) {
    return `Spec path must be a .md file (got "${name}").`
  }
  const abs = isAbsolute(name) ? resolve(name) : resolve(cwd, name)
  const root = resolve(cwd) + sep
  if (!abs.startsWith(root) && abs !== resolve(cwd)) {
    return `Spec path must stay inside the project (${cwd}).`
  }
  return undefined
}

/** Write the spec file (creating parent directories); returns the absolute path. */
export async function writeSpecFile(cwd: string, absPath: string, content: string): Promise<string> {
  await mkdir(dirname(absPath), { recursive: true })
  await writeFile(absPath, content, 'utf8')
  return absPath
}

/**
 * Compose a spec markdown document from stored acceptance criteria
 * (used by the "Spec only — stop" picker option).
 */
export function composeSpecMarkdown(opts: {
  criteria: MetaEntry[]
  title?: string
  notes?: string
  date?: Date
}): string {
  const { criteria, title, notes, date = new Date() } = opts
  const lines: string[] = []
  lines.push(`# ${title ?? 'Spec'}`)
  lines.push('')
  lines.push(`> Generated by adx-workflow spec mode on ${date.toISOString()}`)
  lines.push('')
  lines.push('## Context & goal')
  lines.push('')
  lines.push(notes?.trim() ? notes.trim() : '_No notes recorded — refine this section by hand._')
  lines.push('')
  lines.push('## Acceptance criteria')
  lines.push('')
  if (criteria.length === 0) {
    lines.push('_No criteria were recorded in this session._')
  } else {
    criteria.forEach((entry, i) => {
      const mark = entry.status === 'passed' || entry.status === 'completed' ? 'x' : ' '
      lines.push(`${i + 1}. [${mark}] ${entry.description}`)
    })
  }
  lines.push('')
  return lines.join('\n')
}
